async function dump(id){
  const n = await figma.getNodeByIdAsync(id);
  const lines=[];
  function w(x,depth){
    const pad=' '.repeat(depth*2);
    let desc = pad+x.type+' '+x.name;
    if('characters' in x && x.characters) desc += ' "'+x.characters+'"';
    if(x.type==='RECTANGLE'){ try{ const f=x.fills[0]; if(f&&f.type==='SOLID') desc+=' fill#'+f.color.r.toFixed(2)+','+f.color.g.toFixed(2)+','+f.color.b.toFixed(2); }catch(e){} }
    lines.push(desc);
    if('children' in x) x.children.forEach(c=>w(c,depth+1));
  }
  w(n,0);
  return lines.join('\n');
}
