function rect(parent,x,y,w,h,c,r=0){ const n=figma.createRectangle(); n.x=x;n.y=y;n.resize(w,h); n.fills=c?[{type:'SOLID',color:hex(c)}]:[]; n.cornerRadius=r; parent.appendChild(n); return n; }
