async function makeNav(compName, tabs){
  const comp=figma.createComponent(); comp.name=compName; comp.resize(390,74); comp.x=10000; comp.y=10000;
  rect(comp,0,0,390,1,C.border);
  rect(comp,0,1,390,73,C.surface);
  const n=tabs.length; const slot=390/n;
  for(let i=0;i<n;i++){
    const id=tabs[i][0];
    const grp=frame(comp,id, i*slot, 6, slot, 62, null);
    grp.fills=[];
    // bg pill
