async function dumpNode(id){
  const n = await figma.getNodeByIdAsync(id);
  if(!n) return id+': null';
  const lines=[];
  function w(x,d){
    const pad=' '.repeat(d*2);
    let s=pad+x.type+' '+x.name;
    if('characters' in x) s+=' "'+x.characters+'"';
    if(x.type==='INSTANCE') s+=' compKey='+x.mainComponent.key;
    lines.push(s);
    if('children' in x) x.children.forEach(c=>w(c,d+1));
  }
  w(n,0);
  return lines.join('\n');
}
