const BRAND={r:21/255,g:115/255,b:254/255,a:1};
const WHITE={r:1,g:1,b:1,a:1};
const errs=[];

async function setActive(navId, activeName){
  const nav=await figma.getNodeByIdAsync(navId);
  if(!nav){ errs.push('no nav '+navId); return; }
  const tabs = nav.children.filter(c=>c.type==='FRAME'||c.type==='INSTANCE');
  for(const t of tabs){
    const isActive = t.name===activeName;
    // bg rectangle
    const bg = t.children ? t.children.find(c=>c.name==='bg') : null;
    if(bg && 'fills' in bg){
      if(isActive) bg.fills=[{type:'SOLID',color:BRAND}]; else bg.fills=[];
    }
    // icon instance -> recolor vector
    const icon = t.children ? t.children.find(c=>c.name==='icon') : null;
    if(icon){
      try{
        const v = icon.children[0];
        if(v && 'fills' in v){
          v.fills=[{type:'SOLID',color: isActive? WHITE : {r:0.42,g:0.47,b:0.55,a:1}}];
        }
      }catch(e){ errs.push('icon recolor '+e.message.split('\n')[0]); }
    }
    // label
    const lbl = t.children ? t.children.find(c=>c.name==='label') : null;
    if(lbl && 'fills' in lbl){
      try{
        lbl.fills=[{type:'SOLID',color: isActive? BRAND : {r:0.42,g:0.47,b:0.55,a:1}}];
      }catch(e){ errs.push('lbl '+e.message.split('\n')[0]); }
    }
  }
}

