const out=[];
async function colors(nav){
  const lines=[];
  function w(x){
    if(x.type==='FRAME' && 'children' in x && x.children.some(k=>k.name==='bg')){
      const dict={};
      x.children.forEach(k=>{
        if(k.name==='bg'){ dict.bg=k; }
        if(k.name==='label'){ dict.label=k; }
        if(k.name==='icon'){ dict.icon=k; }
      });
      let bg='?';
      try{ const f=dict.bg.fills[0]; bg=(f&&f.color)? Math.round(f.color.r*255)+','+Math.round(f.color.g*255)+','+Math.round(f.color.b*255) : 'none'; }catch(e){}
      let lbl='?';
      try{ const f=dict.label.fills[0]; lbl=(f&&f.color)? Math.round(f.color.r*255) : '?'; }catch(e){}
      lines.push('  '+x.name+': bg['+bg+'] labelR['+lbl+']');
    }
    if(x.children&&x.children) x.children.forEach(c=>w(c));
  }
  w(nav);
  return lines;
}
