const BRAND={r:21/255,g:115/255,b:254/255};
const NEUT={r:138/255,g:142/255,b:153/255};
const out=[];
function neutralTab(tab){
  try{
    const bg=tab.children.find(k=>k.name==='bg'); bg.fills=[];
    const ic=tab.children.find(k=>k.name==='icon'); ic.children[0].fills=[{type:'SOLID',color:{...NEUT},opacity:1}];
    const lb=tab.children.find(k=>k.name==='label'); lb.fills=[{type:'SOLID',color:{...NEUT},opacity:1}];
  }catch(e){ out.push('neutral err '+e.message.split('\n')[0]); }
}
function activeTab(tab){
  try{
    const bg=tab.children.find(k=>k.name==='bg'); bg.fills=[{type:'SOLID',color:{...BRAND},opacity:1}];
    const ic=tab.children.find(k=>k.name==='icon'); ic.children[0].fills=[{type:'SOLID',color:{r:1,g:1,b:1},opacity:1}];
    const lb=tab.children.find(k=>k.name==='label'); lb.fills=[{type:'SOLID',color:{...BRAND},opacity:1}];
  }catch(e){ out.push('active err '+e.message.split('\n')[0]); }
}
async function apply(navId, activeName){
  const nav=await figma.getNodeByIdAsync(navId);
  if(!nav){ out.push(navId+' null'); return; }
  for(const tab of nav.children){
    if(tab.type!=='FRAME') continue;
    if(tab.name===activeName) activeTab(tab); else neutralTab(tab);
  }
  out.push('done '+navId+' active='+activeName);
}
